public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer hObj = fs.nextIntNullable();
        if (hObj == null) return;
        int H = hObj;
        int W = fs.nextInt();

        int[] height = new int[W];
        long ans = 0;

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int x = fs.nextInt();
                if (x == 0) height[j]++;
                else height[j] = 0;
            }
            ans = Math.max(ans, largestRectangle(height));
        }

        System.out.println(ans);
    }

    static long largestRectangle(int[] h) {
        int n = h.length;
        long best = 0;
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = 0; i <= n; i++) {
            int cur = (i == n ? 0 : h[i]);
            while (!stack.isEmpty() && h[stack.peek()] >= cur) {
                int height = h[stack.pop()];
                int left = stack.isEmpty() ? -1 : stack.peek();
                long width = i - left - 1L;
                best = Math.max(best, width * height);
            }
            stack.push(i);
        }
        return best;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntNullable() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return nextIntNullable();
        }
    }
}

def maximalRectangle(matrix):
    if not matrix or not matrix[0]:
        return 0

    h, w = len(matrix), len(matrix[0])
    heights = [0] * w
    max_area = 0

    for i in range(h):
        for j in range(w):
            if matrix[i][j] == '0':
                heights[j] += 1
            else:
                heights[j] = 0

        stack = []
        for j in range(w + 1):
            cur_h = heights[j] if j < w else 0
            while stack and heights[stack[-1]] > cur_h:
                h_rect = heights[stack.pop()]
                left = stack[-1] if stack else -1
                width = j - left - 1
                max_area = max(max_area, h_rect * width)
            stack.append(j)

    return max_area


