            if matrix[r][c] == 0:
                heights[c] += 1
            else:
                heights[c] = 0

        # Largest rectangle in histogram
        stack = []  # pairs: (start_index, height)
        for i in range(W + 1):
            cur_h = heights[i] if i < W else 0
            start = i
            while stack and stack[-1][1] > cur_h:
                idx, h = stack.pop()
                ans = max(ans, h * (i - idx))
                start = idx
            if not stack or stack[-1][1] < cur_h:
